css:
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#F9F4EC}
.bt-home{--navy:#004877;--ink:#1d1e1f;--ink2:#252627;--cream:#F9F4EC;--sand:#F3E9D9;--white:#fff;--sky:#3C96E7;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.66);--body:rgba(29,30,31,.78);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--sec:clamp(76px,9.5vw,136px);--ease:cubic-bezier(.2,.7,.2,1);display:block;background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:17.5px;font-weight:400;line-height:1.68;-webkit-font-smoothing:antialiased;text-align:left;overflow-wrap:break-word}
.bt-home *,.bt-home *::before,.bt-home *::after{box-sizing:border-box}
.bt-home a{color:inherit;text-decoration:none}
.bt-home ul{list-style:none;margin:0;padding:0}
.bt-home p{margin:0}
.bt-home img{display:block;max-width:100%}
.bt-home svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.bt-home a:focus-visible,.bt-home summary:focus-visible,.bt-home label:focus-visible,.bt-home select:focus-visible,.bt-home input:focus-visible{outline:2px solid var(--sky);outline-offset:3px}
.bt-home .bt-wrap{max-width:1472px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.bt-home .bt-sec{padding-top:var(--sec);padding-bottom:var(--sec)}
.bt-home .bt-sand{background:var(--sand)}
.bt-home .bt-inkbg{background:var(--ink);color:var(--cream)}
.bt-home .bt-vh{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.bt-home .bt-js-only{display:none}
html.bt-js .bt-home .bt-js-only{display:block}

/* type */
.bt-home .bt-kicker{display:flex;align-items:center;gap:14px;font-size:12.5px;line-height:1;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--navy);margin-bottom:24px}
.bt-home .bt-kicker::before{content:"";width:40px;height:1px;background:currentColor;flex-shrink:0}
.bt-home .bt-inkbg .bt-kicker{color:var(--sand)}
.bt-home h1,.bt-home h2,.bt-home h3,.bt-home .bt-cap-n,.bt-home .bt-card-price b,.bt-home .bt-h2{font-family:var(--serif);font-weight:400;font-size:clamp(36px,4.5vw,62px);line-height:1.06;letter-spacing:-.012em;margin:0;text-wrap:balance}
.bt-home .bt-h2 em{font-style:italic;color:var(--navy)}
.bt-home .bt-inkbg .bt-h2 em{color:var(--sand)}
.bt-home .bt-intro{color:var(--body);max-width:56ch}
.bt-home .bt-intro a:not(.bt-link){color:var(--navy);border-bottom:1px solid var(--line);white-space:nowrap}
.bt-home .bt-inkbg .bt-intro{color:rgba(249,244,236,.76)}
.bt-home .bt-head{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(20px,5vw,96px);align-items:end;margin-bottom:clamp(40px,5vw,72px)}
.bt-home .bt-head-side{display:flex;flex-direction:column;align-items:flex-start;gap:22px}
.bt-home .bt-link{display:inline-flex;align-items:center;gap:10px;font-size:12.5px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);border-bottom:1px solid currentColor;padding-bottom:6px;transition:gap .5s var(--ease)}
.bt-home .bt-link:hover{gap:16px}
.bt-home .bt-link svg{width:14px;height:14px}
.bt-home .bt-inkbg .bt-link{color:var(--cream)}

/* buttons */
.bt-home .bt-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 30px;font-family:var(--sans);font-size:12.5px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;text-align:center;border:1px solid var(--navy);border-radius:0;background:var(--navy);color:#fff;cursor:pointer;transition:background .5s var(--ease),color .5s var(--ease),border-color .5s var(--ease)}
.bt-home .bt-btn:hover{background:transparent;color:var(--navy)}
.bt-home .bt-btn-line{background:transparent;color:var(--navy)}
.bt-home .bt-btn-line:hover{background:var(--navy);color:#fff}
.bt-home .bt-btn-cream{background:var(--cream);border-color:var(--cream);color:var(--ink)}
.bt-home .bt-btn-cream:hover{background:transparent;color:var(--cream)}
.bt-home .bt-btn-ghost{background:rgba(20,21,22,.25);border-color:rgba(249,244,236,.5);color:var(--cream)}
.bt-home .bt-btn-ghost:hover{background:var(--cream);border-color:var(--cream);color:var(--ink)}
.bt-home .bt-cta-row{display:flex;flex-wrap:wrap;gap:14px}
.bt-home .bt-icon-btn{display:inline-flex;align-items:center;justify-content:center;width:54px;min-height:54px;flex-shrink:0;border:1px solid var(--line);background:#fff;color:var(--navy);transition:background .4s var(--ease),color .4s var(--ease),border-color .4s var(--ease)}
.bt-home .bt-icon-btn:hover{background:var(--navy);border-color:var(--navy);color:#fff}

/* motion: pure CSS, content is visible without scripts */
@keyframes btRv{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:none}}
@keyframes btRv3{from{opacity:0;transform:perspective(1400px) rotateX(14deg) translateY(40px) scale(.96)}to{opacity:1;transform:perspective(1400px) rotateX(0) translateY(0) scale(1)}}
@keyframes btFade{from{opacity:0}to{opacity:1}}
.bt-home .bt-rv{animation:btRv 1s var(--ease) both}
.bt-home .bt-d1{animation-delay:.12s}.bt-home .bt-d2{animation-delay:.24s}.bt-home .bt-d3{animation-delay:.36s}.bt-home .bt-d4{animation-delay:.5s}
@supports (animation-timeline:view()){
@media (prefers-reduced-motion:no-preference){
.bt-home .bt-sr{animation:btRv linear both;animation-timeline:view();animation-range:entry 0% entry 40%}
.bt-home .bt-sr3{animation:btRv3 linear both;animation-timeline:view();animation-range:entry 0% entry 55%;transform-origin:50% 100%}
.bt-home .bt-sro{animation:btFade linear both;animation-timeline:view();animation-range:entry 0% entry 40%}
}}

/* 1. hero */
.bt-home .bt-hero{position:relative;overflow:hidden;background:#151617;color:var(--cream)}
.bt-home .bt-hero-bg{position:absolute;inset:0}
.bt-home .bt-hb{position:absolute;inset:0;width:100%;height:100%;max-width:none;object-fit:cover}
.bt-home .bt-hb1{animation:btZoom 26s ease-in-out infinite alternate}
.bt-home .bt-hb2{opacity:0;animation:btHb 22s ease-in-out infinite}
@keyframes btZoom{from{transform:scale(1.02)}to{transform:scale(1.1)}}
@keyframes btHb{0%,40%{opacity:0;transform:scale(1.02)}50%,90%{opacity:1}100%{opacity:0;transform:scale(1.1)}}
.bt-home .bt-hero::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(17,18,19,.9) 0%,rgba(17,18,19,.72) 30%,rgba(17,18,19,.28) 62%,rgba(17,18,19,.42) 100%),linear-gradient(0deg,rgba(17,18,19,.55) 0%,rgba(17,18,19,0) 34%)}
.bt-home .bt-hero-in{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,.75fr);gap:clamp(24px,4vw,72px);align-items:center;min-height:min(860px,calc(100vh - 193px));padding-top:clamp(52px,5vw,84px);padding-bottom:clamp(52px,5vw,84px)}
.bt-home .bt-hero .bt-kicker{color:var(--sand)}
.bt-home .bt-hero h1{font-family:var(--serif);font-weight:400;font-size:clamp(46px,6.3vw,98px);line-height:.98;letter-spacing:-.018em;color:#fff;margin:0 0 30px;text-wrap:balance}
.bt-home .bt-hero h1 em{display:block;font-style:italic;font-size:.42em;line-height:1.3;letter-spacing:0;color:rgba(249,244,236,.88);margin-top:.7em}
.bt-home .bt-hero-lead{font-size:clamp(17px,1.3vw,19.5px);line-height:1.7;font-weight:300;color:rgba(249,244,236,.86);max-width:50ch;margin-bottom:40px}

.bt-home .bt-hero-visual{position:relative;min-width:0;width:100%;max-width:430px;margin-left:auto;padding:26px 28px 28px;background:rgba(18,19,20,.5);-webkit-backdrop-filter:blur(18px) saturate(1.15);backdrop-filter:blur(18px) saturate(1.15);border:1px solid rgba(249,244,236,.2)}
.bt-home .bt-hv-k{display:flex;justify-content:space-between;align-items:center;font-size:11px;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:rgba(249,244,236,.7);padding-bottom:16px;border-bottom:1px solid rgba(249,244,236,.16)}
.bt-home .bt-hv-k i{font-style:normal;color:var(--sand)}
.bt-home .bt-ht{position:absolute;left:50%;top:50%;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-stage{--w:clamp(118px,10.6vw,160px);--t:8px;position:relative;height:calc(var(--w) * 2 + 76px);display:grid;place-items:center;perspective:1300px}
.bt-home .bt-slab{position:relative;width:var(--w);height:calc(var(--w) * 2);transform-style:preserve-3d;animation:btSway 6.5s ease-in-out infinite alternate;will-change:transform}
@keyframes btSway{from{transform:rotateX(5deg) rotateY(-38deg)}to{transform:rotateX(5deg) rotateY(38deg)}}
.bt-home .bt-slab-face{position:absolute;inset:0;overflow:hidden;backface-visibility:hidden;-webkit-backface-visibility:hidden;background:#d6d0c6}
.bt-home .bt-slab-front{transform:translateZ(calc(var(--t) / 2))}
.bt-home .bt-slab-back{transform:rotateY(180deg) translateZ(calc(var(--t) / 2));background:repeating-linear-gradient(90deg,#c9c2b6 0 10px,#beb7ab 10px 12px)}
.bt-home .bt-slab-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity 1s var(--ease)}
.bt-home .bt-sheen{position:absolute;inset:0;background:linear-gradient(104deg,rgba(255,255,255,0) 34%,rgba(255,255,255,.75) 50%,rgba(255,255,255,0) 66%);background-size:340% 100%;mix-blend-mode:screen;opacity:var(--sheen,.3);animation:btSheen 16s ease-in-out infinite alternate;transition:opacity 1s var(--ease);pointer-events:none}
@keyframes btSheen{from{background-position:96% 0}to{background-position:4% 0}}
.bt-home .bt-slab-edge{position:absolute;background:linear-gradient(#d9d3c9,#c4bdb1)}
.bt-home .bt-slab-l,.bt-home .bt-slab-r{top:0;bottom:0;width:var(--t);left:calc(50% - var(--t) / 2)}
.bt-home .bt-slab-l{transform:rotateY(-90deg) translateZ(calc(var(--w) / 2))}
.bt-home .bt-slab-r{transform:rotateY(90deg) translateZ(calc(var(--w) / 2))}
.bt-home .bt-slab-t,.bt-home .bt-slab-b{left:0;right:0;height:var(--t);top:calc(50% - var(--t) / 2)}
.bt-home .bt-slab-t{transform:rotateX(90deg) translateZ(var(--w))}
.bt-home .bt-slab-b{transform:rotateX(-90deg) translateZ(var(--w))}
.bt-home .bt-slab-shadow{position:absolute;left:50%;top:calc(50% + var(--w) + 14px);width:calc(var(--w) * 1.25);height:26px;transform:translateX(-50%);background:radial-gradient(closest-side,rgba(0,0,0,.7),rgba(0,0,0,0));filter:blur(6px);animation:btShadow 16s ease-in-out infinite alternate;pointer-events:none}
@keyframes btShadow{0%,100%{transform:translateX(-50%) scaleX(.78)}50%{transform:translateX(-50%) scaleX(1)}}
.bt-home .bt-slab-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity 1.2s var(--ease)}
.bt-home .bt-stage.bt-3d-on .bt-slab-canvas{opacity:1}
.bt-home .bt-stage.bt-3d-on .bt-slab,.bt-home .bt-stage.bt-3d-on .bt-slab-shadow{opacity:0;animation-play-state:paused;transition:opacity .8s var(--ease)}
.bt-home .bt-stage.bt-3d-on .bt-sheen{animation-play-state:paused}
.bt-home .bt-ribbon{position:relative;z-index:2;overflow:hidden;border-top:1px solid rgba(249,244,236,.16);background:rgba(17,18,19,.46);-webkit-backdrop-filter:blur(16px) saturate(1.1);backdrop-filter:blur(16px) saturate(1.1);-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 9%,#000 91%,transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 9%,#000 91%,transparent 100%)}
.bt-home .bt-ribbon-track{display:flex;width:max-content;animation:btRibbon 54s linear infinite}
.bt-home .bt-ribbon:hover .bt-ribbon-track{animation-play-state:paused}
.bt-home .bt-ribbon ul{display:flex;align-items:center;flex:none}
.bt-home .bt-ribbon li{display:flex;align-items:center;white-space:nowrap;height:68px;font-family:var(--serif);font-style:italic;font-weight:400;font-size:clamp(19px,1.5vw,23px);color:var(--cream);font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-home .bt-ribbon li:nth-child(even){font-family:var(--sans);font-style:normal;font-size:11.5px;font-weight:500;letter-spacing:.26em;text-transform:uppercase;color:var(--sand)}
.bt-home .bt-ribbon li::after{content:"";flex:none;width:7px;height:7px;margin:0 clamp(26px,3vw,48px);border:1px solid var(--sand);transform:rotate(45deg);opacity:.8}
@keyframes btRibbon{to{transform:translateX(-50%)}}
.bt-home .bt-hero-foot{display:block;padding-top:16px;border-top:1px solid rgba(249,244,236,.16)}
.bt-home .bt-cap{display:none;min-width:0}
.bt-home .bt-cap-k{font-size:11px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:rgba(249,244,236,.66);margin-bottom:6px}
.bt-home .bt-cap-n{font-family:var(--serif);font-size:28px;line-height:1.1;color:#fff}
.bt-home .bt-cap-m{font-size:14.5px;font-weight:300;color:rgba(249,244,236,.8);margin:4px 0 0}
.bt-home .bt-cap-row{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}
.bt-home .bt-cap .bt-link{color:var(--cream);font-size:11.5px;flex-shrink:0}
.bt-home .bt-swatches{display:flex;gap:10px;margin-top:20px}
.bt-home .bt-sw{position:relative;flex:1;aspect-ratio:1;max-width:56px;cursor:pointer;display:block;outline:1px solid rgba(249,244,236,0);outline-offset:3px;transition:outline-color .5s var(--ease),transform .5s var(--ease)}
.bt-home .bt-sw img{width:100%;height:100%;object-fit:cover}
.bt-home .bt-sw:hover{transform:translateY(-3px)}
.bt-home .bt-ht1:checked~.bt-stage .bt-si1,.bt-home .bt-ht2:checked~.bt-stage .bt-si2,.bt-home .bt-ht3:checked~.bt-stage .bt-si3,.bt-home .bt-ht4:checked~.bt-stage .bt-si4,.bt-home .bt-ht5:checked~.bt-stage .bt-si5{opacity:1}
.bt-home .bt-ht1:checked~.bt-stage{--sheen:.3}.bt-home .bt-ht2:checked~.bt-stage{--sheen:.1}.bt-home .bt-ht3:checked~.bt-stage{--sheen:.14}.bt-home .bt-ht4:checked~.bt-stage{--sheen:.5}.bt-home .bt-ht5:checked~.bt-stage{--sheen:.16}
.bt-home .bt-ht1:checked~.bt-hero-foot .bt-cap1,.bt-home .bt-ht2:checked~.bt-hero-foot .bt-cap2,.bt-home .bt-ht3:checked~.bt-hero-foot .bt-cap3,.bt-home .bt-ht4:checked~.bt-hero-foot .bt-cap4,.bt-home .bt-ht5:checked~.bt-hero-foot .bt-cap5{display:block;animation:btRv .7s var(--ease) both}
.bt-home .bt-ht1:checked~.bt-hero-foot .bt-sw1,.bt-home .bt-ht2:checked~.bt-hero-foot .bt-sw2,.bt-home .bt-ht3:checked~.bt-hero-foot .bt-sw3,.bt-home .bt-ht4:checked~.bt-hero-foot .bt-sw4,.bt-home .bt-ht5:checked~.bt-hero-foot .bt-sw5{outline-color:rgba(249,244,236,.95)}
.bt-home .bt-ht1:focus-visible~.bt-hero-foot .bt-sw1,.bt-home .bt-ht2:focus-visible~.bt-hero-foot .bt-sw2,.bt-home .bt-ht3:focus-visible~.bt-hero-foot .bt-sw3,.bt-home .bt-ht4:focus-visible~.bt-hero-foot .bt-sw4,.bt-home .bt-ht5:focus-visible~.bt-hero-foot .bt-sw5{outline:2px solid var(--sky)}

/* 2. trust strip */

/* 3. BT Specials cards + quick view */
.bt-home .bt-specials{position:relative}
.bt-home .bt-qv{position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-cv{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(48px,5vw,68px) clamp(18px,2.1vw,32px)}
.bt-home .bt-slot{min-width:0;display:flex}
.bt-home .bt-card{position:relative;display:flex;flex-direction:column;min-width:0;width:100%}
.bt-home .bt-card-media{perspective:1100px}
.bt-home .bt-card-imgs{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--sand);transition:transform .9s var(--ease),box-shadow .9s var(--ease);transform-style:preserve-3d;will-change:transform}
.bt-home .bt-slot:hover .bt-card-imgs{transform:rotateX(3deg) rotateY(-4deg) translateY(-6px);box-shadow:26px 34px 44px -30px rgba(29,30,31,.5)}
.bt-home .bt-ci{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:opacity .8s var(--ease),transform 1.6s var(--ease)}
.bt-home .bt-ci-r{opacity:0}
.bt-home .bt-cv-r:checked~.bt-card-media .bt-ci-r{opacity:1}
.bt-home .bt-cv-r:checked~.bt-card-media .bt-ci-s{opacity:0}
.bt-home .bt-badge{position:absolute;left:0;top:16px;z-index:2;background:var(--navy);color:#fff;font-size:10.5px;line-height:1;font-weight:500;letter-spacing:.22em;text-transform:uppercase;padding:9px 13px}
.bt-home .bt-seg{display:grid;grid-template-columns:1fr 1fr}
.bt-home .bt-seg label{display:flex;align-items:center;justify-content:center;min-height:42px;padding:0 8px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;text-align:center;cursor:pointer;border:1px solid var(--ink);border-top:0;background:#fff;color:var(--ink);transition:background .4s var(--ease),color .4s var(--ease)}
.bt-home .bt-seg label+label{border-left:0}
.bt-home .bt-cv-s:checked~.bt-card-media .bt-seg-s,.bt-home .bt-cv-r:checked~.bt-card-media .bt-seg-r{background:var(--ink);color:#fff}
.bt-home .bt-cv-s:focus-visible~.bt-card-media .bt-seg-s,.bt-home .bt-cv-r:focus-visible~.bt-card-media .bt-seg-r{outline:2px solid var(--sky);outline-offset:-3px}
.bt-home .bt-card-body{display:flex;flex-direction:column;flex:1;min-width:0}
.bt-home .bt-card-k{font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin:20px 0 8px}
.bt-home .bt-card h3{font-family:var(--serif);font-weight:400;font-size:clamp(25px,2vw,30px);line-height:1.12;margin:0 0 6px}
.bt-home .bt-card h3 a:hover{color:var(--navy)}
.bt-home .bt-card-meta{font-size:15px;font-weight:300;line-height:1.5;color:var(--body)}
.bt-home .bt-card-price{display:flex;align-items:baseline;gap:7px;margin:16px 0 18px;padding-top:14px;border-top:1px solid var(--line);font-size:14px;color:var(--body)}
.bt-home .bt-card-price b{font-family:var(--serif);font-weight:400;font-size:30px;line-height:1;color:var(--navy)}
.bt-home .bt-card-cta{margin-top:auto;display:flex;gap:10px}
.bt-home .bt-card-cta .bt-btn{flex:1;padding:0 12px;font-size:11.5px;letter-spacing:.18em}
.bt-home .bt-qv-only{display:none}
.bt-home .bt-qv-scrim{position:fixed;inset:0;z-index:990;background:rgba(17,18,19,.66);opacity:0;visibility:hidden;cursor:pointer;transition:opacity .5s var(--ease),visibility 0s .5s}
.bt-home .bt-qv:not(.bt-qv0):checked~.bt-qv-scrim{opacity:1;visibility:visible;transition-delay:0s}
@keyframes btQv{from{opacity:0;transform:translate(-50%,-46%) scale(.97)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes btQvM{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}
.bt-home .bt-qv1:checked~.bt-wrap .bt-slot1 .bt-card,.bt-home .bt-qv2:checked~.bt-wrap .bt-slot2 .bt-card,.bt-home .bt-qv3:checked~.bt-wrap .bt-slot3 .bt-card,.bt-home .bt-qv4:checked~.bt-wrap .bt-slot4 .bt-card,.bt-home .bt-qv5:checked~.bt-wrap .bt-slot5 .bt-card,.bt-home .bt-qv6:checked~.bt-wrap .bt-slot6 .bt-card,.bt-home .bt-qv7:checked~.bt-wrap .bt-slot7 .bt-card,.bt-home .bt-qv8:checked~.bt-wrap .bt-slot8 .bt-card{position:fixed;z-index:1000;left:50%;top:50%;transform:translate(-50%,-50%);width:min(1180px,calc(100vw - 48px));height:min(790px,calc(100vh - 48px));display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);grid-template-rows:minmax(0,1fr);background:var(--cream);overflow:hidden;animation:btQv .6s var(--ease) both;box-shadow:0 60px 120px -40px rgba(0,0,0,.7)}
