.bt-home .bt-cfr7:checked~.bt-cf-stage .bt-cfs3{--d:3;--a:3;--o:0}
.bt-home .bt-cfr7:checked~.bt-cf-stage .bt-cfs4{--d:-3;--a:3;--o:0}
.bt-home .bt-cfr7:checked~.bt-cf-stage .bt-cfs5{--d:-2;--a:2;--o:1}
