.bt-home .bt-cfr7:focus-visible~.bt-cf-nav .bt-cf-d7{outline:2px solid var(--sky);outline-offset:4px}

/* 5. shop by look: 3D sample rack */
.bt-home .bt-rack{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:clamp(8px,1.6vw,28px)}
.bt-home .bt-rk{display:block;min-width:0;text-align:center;perspective:900px;perspective-origin:50% 42%}
.bt-home .bt-rk-slab{position:relative;display:block;aspect-ratio:1/2;margin:0 9% 0 9%;transform:rotateY(-40deg);transform-style:preserve-3d;transition:transform 1.1s var(--ease),box-shadow 1.1s var(--ease);box-shadow:-40px 44px 50px -30px rgba(29,30,31,.55)}
.bt-home .bt-rk-slab img{width:100%;height:100%;object-fit:cover}
.bt-home .bt-rk-slab::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(100deg,rgba(255,255,255,0) 30%,rgba(255,255,255,.34) 48%,rgba(255,255,255,0) 64%);background-size:300% 100%;background-position:100% 0;transition:background-position 1.4s var(--ease);pointer-events:none}
.bt-home .bt-rk-slab::after{content:"";position:absolute;top:0;bottom:0;right:0;width:14px;background:linear-gradient(90deg,#b7b0a4,#ddd7cd);transform-origin:100% 50%;transform:rotateY(-90deg)}
.bt-home .bt-rk:hover .bt-rk-slab,.bt-home .bt-rk:focus-visible .bt-rk-slab{transform:rotateY(0deg) translateZ(40px);box-shadow:0 46px 50px -34px rgba(29,30,31,.55)}
.bt-home .bt-rk:hover .bt-rk-slab::before{background-position:0 0}
.bt-home .bt-rk-t{display:block;margin-top:30px}
.bt-home .bt-rk-t b{display:block;font-family:var(--serif);font-weight:400;font-size:clamp(19px,1.75vw,27px);line-height:1.15}
.bt-home .bt-rk-t small{display:inline-flex;align-items:center;gap:8px;margin-top:10px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy)}
.bt-home .bt-rk-t svg{width:13px;height:13px;transition:transform .6s var(--ease)}
.bt-home .bt-rk:hover .bt-rk-t svg{transform:translateX(5px)}

/* 6. visualiser teaser: one room, interchangeable tiles */
.bt-home .bt-viz{display:grid;grid-template-columns:minmax(0,.74fr) minmax(0,1.26fr);gap:clamp(32px,5.5vw,96px);align-items:center}
.bt-home .bt-viz .bt-h2{margin-bottom:26px}
.bt-home .bt-viz-list{margin:30px 0 38px;border-top:1px solid var(--line)}
.bt-home .bt-viz-list li{display:flex;gap:18px;padding:15px 0;border-bottom:1px solid var(--line);font-size:16px;color:var(--body)}
.bt-home .bt-viz-list b{flex:0 0 96px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);padding-top:6px}
.bt-home .bt-viz-visual{position:relative;min-width:0;perspective:1800px}
.bt-home .bt-rt{position:absolute;left:50%;top:40%;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-room{position:relative;aspect-ratio:1280/714;overflow:hidden;background:#cfc8bc;transform:rotateY(-9deg) rotateX(2deg);transform-origin:100% 50%;transition:transform 1.2s var(--ease);box-shadow:-40px 50px 70px -44px rgba(29,30,31,.6)}
.bt-home .bt-viz-visual:hover .bt-room{transform:rotateY(0deg) rotateX(0deg)}
.bt-home .bt-room img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity 1s var(--ease)}
.bt-home .bt-room-tag{position:absolute;left:0;top:0;z-index:2;display:none;background:rgba(17,18,19,.78);color:#fff;padding:12px 18px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase}
.bt-home .bt-rt1:checked~.bt-room .bt-rf1,.bt-home .bt-rt2:checked~.bt-room .bt-rf2,.bt-home .bt-rt3:checked~.bt-room .bt-rf3,.bt-home .bt-rt4:checked~.bt-room .bt-rf4{opacity:1}
.bt-home .bt-rt1:checked~.bt-room .bt-rg1,.bt-home .bt-rt2:checked~.bt-room .bt-rg2,.bt-home .bt-rt3:checked~.bt-room .bt-rg3,.bt-home .bt-rt4:checked~.bt-room .bt-rg4{display:block}
.bt-home .bt-room-opts{position:relative;z-index:2;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:-34px 0 0 clamp(16px,4vw,64px);background:#fff;box-shadow:0 30px 44px -30px rgba(29,30,31,.45)}
.bt-home .bt-ro{display:flex;align-items:center;gap:12px;padding:14px 16px;cursor:pointer;border-left:1px solid var(--line);transition:background .5s var(--ease),color .5s var(--ease);min-width:0}
