.bt-home .bt-ro img{width:44px;height:44px;object-fit:cover;flex-shrink:0}
.bt-home .bt-ro b{display:block;font-family:var(--serif);font-weight:400;font-size:clamp(15px,1.25vw,19px);line-height:1.15}
.bt-home .bt-ro small{display:block;font-size:10.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin-top:4px}
.bt-home .bt-ro:hover{background:var(--sand)}
.bt-home .bt-rt1:checked~.bt-room-opts .bt-ro1,.bt-home .bt-rt2:checked~.bt-room-opts .bt-ro2,.bt-home .bt-rt3:checked~.bt-room-opts .bt-ro3,.bt-home .bt-rt4:checked~.bt-room-opts .bt-ro4{background:var(--navy);color:#fff}
.bt-home .bt-rt1:checked~.bt-room-opts .bt-ro1 small,.bt-home .bt-rt2:checked~.bt-room-opts .bt-ro2 small,.bt-home .bt-rt3:checked~.bt-room-opts .bt-ro3 small,.bt-home .bt-rt4:checked~.bt-room-opts .bt-ro4 small{color:rgba(255,255,255,.7)}
.bt-home .bt-rt1:focus-visible~.bt-room-opts .bt-ro1,.bt-home .bt-rt2:focus-visible~.bt-room-opts .bt-ro2,.bt-home .bt-rt3:focus-visible~.bt-room-opts .bt-ro3,.bt-home .bt-rt4:focus-visible~.bt-room-opts .bt-ro4{outline:2px solid var(--sky);outline-offset:-2px}

/* 7. complete the room */

/* 8. story */
.bt-home .bt-story{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);gap:clamp(40px,7vw,120px);align-items:center}
.bt-home .bt-story-fig{position:relative;margin:0;margin-right:clamp(16px,3vw,44px);perspective:1600px}
