.bt-home .bt-story p+p{margin-top:16px}
.bt-home .bt-story .bt-link{margin-top:34px}

/* 9. showroom */
.bt-home .bt-show{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(32px,6vw,96px);align-items:stretch}
.bt-home .bt-show .bt-h2{margin-bottom:22px}
.bt-home .bt-show-nap{font-family:var(--serif);font-style:normal;font-size:clamp(23px,2vw,29px);line-height:1.3;margin:30px 0 6px}
.bt-home .bt-show-tel{display:inline-block;font-family:var(--serif);font-size:clamp(23px,2vw,29px);line-height:1.3;color:var(--navy);border-bottom:1px solid var(--line);transition:border-color .4s var(--ease)}
