.bt-home .bt-brands-h p{font-family:var(--serif);font-size:clamp(24px,2.4vw,34px);line-height:1.2}
.bt-home .bt-logos{display:flex;flex-wrap:wrap;justify-content:center;padding:0 1px 1px 0}
.bt-home .bt-logos li{flex:0 0 16.666%;display:flex;align-items:center;justify-content:center;height:clamp(104px,10vw,148px);padding:18px clamp(14px,2vw,34px);background:#fff;border:1px solid var(--line);margin:0 -1px -1px 0}
.bt-home .bt-logos img{max-width:100%;max-height:62px;width:auto;height:auto;object-fit:contain;filter:grayscale(1) contrast(1.05);opacity:.78;transition:filter .6s var(--ease),opacity .6s var(--ease),transform .6s var(--ease)}
