.bt-home .bt-logos-more b{font-family:var(--serif);font-weight:400;font-style:italic;font-size:clamp(17px,1.5vw,21px);line-height:1.15;color:var(--navy);font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-home .bt-logos-more small{font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink);opacity:.7}

/* 11. faq */
.bt-home .bt-faq{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(32px,6vw,104px);align-items:start}
