.bt-home .bt-faq summary{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;cursor:pointer;list-style:none;font-family:var(--serif);font-size:clamp(21px,1.9vw,27px);line-height:1.25;transition:color .4s var(--ease)}
.bt-home .bt-faq summary::-webkit-details-marker{display:none}
.bt-home .bt-faq summary:hover{color:var(--navy)}
.bt-home .bt-faq summary svg{width:20px;height:20px;color:var(--navy);transition:transform .6s var(--ease)}
.bt-home .bt-faq details[open] summary svg{transform:rotate(45deg)}
.bt-home .bt-faq-a{padding:0 44px 28px 0;color:var(--body);max-width:68ch}
