.bt-home .bt-close .bt-kicker::after{content:"";width:40px;height:1px;background:currentColor}
.bt-home .bt-close h2{font-family:var(--serif);font-weight:400;font-size:clamp(44px,6.8vw,104px);line-height:1;letter-spacing:-.018em;color:#fff;margin:0 0 26px}
