/* responsive */
/* ---- shop by category ---- */
.bt-home .bt-catgrid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(12px,1.3vw,20px);perspective:2400px}
.bt-home .bt-cat-r{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-auto-rows:clamp(236px,21.5vw,330px);gap:clamp(12px,1.3vw,20px);perspective:2000px;min-width:0}
.bt-home .bt-cat-r .bt-cat{grid-column:span 3}
