.bt-home .bt-cat{position:relative;isolation:isolate;display:flex;align-items:flex-end;overflow:hidden;min-width:0;color:#fff;background:var(--ink);transition:transform .9s var(--ease),box-shadow .9s var(--ease);will-change:transform}
