.bt-home .bt-cat::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(112deg,rgba(255,255,255,0) 38%,rgba(255,255,255,.22) 50%,rgba(255,255,255,0) 62%);background-size:280% 100%;background-position:120% 0;transition:background-position 1.3s var(--ease);pointer-events:none}
