.bt-home .bt-cat-t{width:100%;min-width:0;padding:clamp(18px,1.8vw,30px)}
.bt-home .bt-cat h3{font-size:clamp(27px,2.3vw,36px);line-height:1.05}
.bt-home .bt-cat-a{color:#fff}
.bt-home .bt-cat-a::after{content:"";position:absolute;inset:0}
.bt-home .bt-cat-t p{font-size:14.5px;font-weight:300;line-height:1.5;color:rgba(255,255,255,.86);margin:8px 0 0;max-width:46ch}
.bt-home .bt-cat-s .bt-cat-t p{display:none}
.bt-home .bt-cat-subs{position:relative;z-index:2;display:flex;flex-wrap:wrap;gap:6px;max-height:0;opacity:0;overflow:hidden;transform:translateY(10px);transition:max-height .8s var(--ease),opacity .6s var(--ease),transform .8s var(--ease),margin .8s var(--ease)}
