.bt-home .bt-cat-subs a{display:block;font-size:12px;line-height:1;letter-spacing:.05em;padding:8px 12px;border:1px solid rgba(255,255,255,.42);border-radius:999px;background:rgba(17,18,19,.34);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);white-space:nowrap;transition:background .4s var(--ease),color .4s var(--ease),border-color .4s var(--ease)}
.bt-home .bt-cat-subs a:hover{background:var(--cream);border-color:var(--cream);color:var(--ink)}
.bt-home .bt-cat-go{display:inline-flex;align-items:center;gap:10px;margin-top:16px;font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;border-bottom:1px solid rgba(255,255,255,.7);padding-bottom:6px;transition:gap .5s var(--ease)}
