.bt-home .bt-cat:hover .bt-cat-go{gap:16px}
.bt-home .bt-cat-xl h3{font-size:clamp(40px,4.2vw,66px)}
.bt-home .bt-cat-xl .bt-cat-t{padding:clamp(22px,2.6vw,44px)}
