.bt-home .bt-cat-chip{position:absolute;left:clamp(16px,1.7vw,26px);top:clamp(14px,1.5vw,22px);z-index:2;display:flex;align-items:center;gap:12px;padding:10px 14px 10px 12px;background:rgba(249,244,236,.94);color:var(--navy);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 18px 30px -18px rgba(17,18,19,.7);transition:transform .6s var(--ease),background .4s var(--ease)}
