.bt-home .bt-cat-chip i{width:8px;height:8px;background:var(--navy);transform:rotate(45deg);flex:none}
.bt-home .bt-cat-chip b{display:block;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;line-height:1.2}
.bt-home .bt-cat-chip small{display:block;font-family:var(--serif);font-style:italic;font-size:15px;line-height:1.2;color:var(--ink)}
.bt-home .bt-cat-chip svg{width:14px;height:14px;flex:none}

/* ---- car park sale + BT specials promo ---- */
.bt-home .bt-nb{white-space:nowrap}
.bt-home .bt-promo{padding-bottom:var(--sec)}
.bt-home .bt-promo-in{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(0,1fr);gap:clamp(12px,1.3vw,20px);align-items:stretch}
.bt-home .bt-sale{position:relative;isolation:isolate;overflow:hidden;display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);align-items:center;gap:clamp(10px,2vw,30px);min-height:clamp(480px,43vw,620px);padding:clamp(28px,3.6vw,60px);color:#fff;background:linear-gradient(150deg,#004877 0%,#00365b 46%,#001a2e 100%)}
.bt-home .bt-sale-floor{position:absolute;left:0;right:0;bottom:0;z-index:-1;height:46%;overflow:hidden;perspective:420px;perspective-origin:50% 0;opacity:.6;-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 62%);mask-image:linear-gradient(180deg,transparent 0,#000 62%);pointer-events:none}
.bt-home .bt-sale-floor i{position:absolute;left:-130%;right:-130%;top:0;height:1300px;transform-origin:50% 0;transform:translateZ(-360px) rotateX(76deg);background-image:linear-gradient(rgba(174,211,245,.42) 2px,transparent 2px),linear-gradient(90deg,rgba(174,211,245,.42) 2px,transparent 2px);background-size:92px 92px;animation:btSaleFloor 20s linear infinite}
@keyframes btSaleFloor{to{background-position:0 184px}}
.bt-home .bt-sale .bt-kicker{color:#AED3F5;margin-bottom:22px}
.bt-home .bt-sale-date{display:flex;align-items:flex-end;gap:16px;margin-bottom:6px}
.bt-home .bt-sale-date b{font-family:var(--serif);font-weight:400;font-size:clamp(96px,10.5vw,168px);line-height:.78;letter-spacing:-.03em;background:linear-gradient(180deg,#fff 0%,#AED3F5 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.bt-home .bt-sale-date p{margin:0 0 6px;display:flex;flex-direction:column;gap:4px}
.bt-home .bt-sale-date i{font-family:var(--serif);font-style:italic;font-size:clamp(26px,2.5vw,38px);line-height:1;color:#fff}
.bt-home .bt-sale-date span{font-size:11.5px;font-weight:500;letter-spacing:.26em;text-transform:uppercase;color:#AED3F5}
.bt-home .bt-sale .bt-h2{font-size:clamp(40px,4.6vw,70px);color:#fff;margin-top:18px}
.bt-home .bt-sale .bt-h2 em{color:#AED3F5}
.bt-home .bt-sale-p{font-size:16.5px;font-weight:300;line-height:1.65;color:rgba(255,255,255,.86);margin:18px 0 0;max-width:46ch}
.bt-home .bt-sale-count{align-items:baseline;gap:12px;margin:22px 0 0}
html.bt-js .bt-home .bt-sale-count.bt-js-only{display:flex}
.bt-home .bt-sale-count b{display:inline-flex;align-items:center;justify-content:center;min-width:62px;height:62px;padding:0 12px;font-family:var(--serif);font-weight:400;font-size:38px;line-height:1;color:var(--navy);background:var(--cream);box-shadow:0 16px 26px -16px rgba(0,0,0,.7);animation:btCountFlip 1.1s var(--ease) both}
@keyframes btCountFlip{from{transform:perspective(300px) rotateX(-90deg);opacity:0}to{transform:none;opacity:1}}
.bt-home .bt-sale-count span{font-size:11.5px;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:#AED3F5}
.bt-home .bt-sale-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.bt-home .bt-sale-cta .bt-btn-cream{color:var(--navy)}
.bt-home .bt-sale-cta .bt-btn-ghost{background:rgba(0,26,46,.3);border-color:rgba(174,211,245,.6);color:#fff}
.bt-home .bt-sale-cta .bt-btn-ghost:hover{background:var(--cream);border-color:var(--cream);color:var(--navy)}
.bt-home .bt-fan{--fw:clamp(118px,11.4vw,176px);--gap:calc(var(--fw) * .43);position:relative;height:calc(var(--fw) * 2.5);perspective:1300px;perspective-origin:30% 40%;justify-self:stretch;animation:btFanFloat 7s ease-in-out infinite alternate}
.bt-home .bt-fan-s{position:absolute;left:0;top:50%;width:var(--fw);height:calc(var(--fw) * 2);margin-top:calc(var(--fw) * -1);display:block;transform-origin:0 50%;transform:translate3d(calc(var(--i) * var(--gap)),calc(var(--i) * -5px),calc(var(--i) * -70px)) rotateY(-46deg);box-shadow:-26px 30px 44px -22px rgba(0,10,20,.85);transition:transform 1.1s var(--ease)}
.bt-home .bt-fan-s img{width:100%;height:100%;object-fit:cover}
.bt-home .bt-fan-s::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,rgba(255,255,255,.28) 0%,rgba(255,255,255,0) 34%,rgba(0,20,36,.26) 100%);pointer-events:none}
.bt-home .bt-sale:hover .bt-fan-s{transform:translate3d(calc(var(--i) * var(--gap) * 1.24),calc(var(--i) * -9px),calc(var(--i) * -40px)) rotateY(-30deg)}
@keyframes btFanFloat{from{transform:translateY(-8px)}to{transform:translateY(10px)}}
.bt-home .bt-btp{display:flex;flex-direction:column;justify-content:center;padding:clamp(28px,3.2vw,52px);background:var(--sand);border:1px solid var(--line);min-width:0}
.bt-home .bt-btp-h{font-size:clamp(30px,3vw,44px);line-height:1.08}
.bt-home .bt-btp-h em{font-style:italic;color:var(--navy)}
.bt-home .bt-btp-p{color:var(--body);margin:18px 0 0}
.bt-home .bt-btp-mos{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:26px;perspective:900px}
.bt-home .bt-btp-mos a{display:block;overflow:hidden;aspect-ratio:1;background:var(--cream);box-shadow:0 0 0 1px var(--line);transition:transform .7s var(--ease),box-shadow .7s var(--ease)}
.bt-home .bt-btp-mos a:hover{transform:translateY(-6px) rotateX(10deg) rotateY(-10deg);box-shadow:14px 22px 28px -18px rgba(17,18,19,.55)}
.bt-home .bt-btp-mos img{width:100%;height:100%;object-fit:cover}
.bt-home .bt-btp-cta{display:flex;flex-wrap:wrap;align-items:center;gap:18px 26px;margin-top:30px}
html.bt-sale-over .bt-home .bt-sale{display:none}
html.bt-sale-over .bt-home .bt-promo-in{grid-template-columns:minmax(0,1fr)}
html.bt-sale-over .bt-home .bt-btp-mos{grid-template-columns:repeat(8,minmax(0,1fr));max-width:880px}

/* ---- car park sale notice (CSS only: unchecked box shows it) ---- */
.bt-home .bt-pop-x{position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-pop{position:fixed;inset:0;z-index:1200;display:grid;place-items:center;padding:20px;overflow-y:auto;animation:btPopIn .7s 1.2s both}
.bt-home .bt-pop-x:checked~.bt-pop,html.bt-sale-over .bt-home .bt-pop,.bt-home:has(#car-park-sale:target) .bt-pop,.bt-home:has(#bt-specials:target) .bt-pop{display:none}
@keyframes btPopIn{from{opacity:0;visibility:hidden}to{opacity:1;visibility:visible}}
.bt-home .bt-pop-scrim{position:fixed;inset:0;background:rgba(0,16,29,.72);-webkit-backdrop-filter:blur(5px);backdrop-filter:blur(5px);cursor:pointer}
.bt-home .bt-pop-card{position:relative;display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1fr);width:min(900px,100%);background:var(--cream);box-shadow:0 60px 120px -40px rgba(0,0,0,.8);animation:btPopCard 1s 1.25s var(--ease) both}
@keyframes btPopCard{from{opacity:0;transform:perspective(1300px) rotateX(16deg) translateY(54px) scale(.95)}to{opacity:1;transform:none}}
.bt-home .bt-pop-close{position:absolute;right:10px;top:10px;z-index:2;display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;cursor:pointer;color:var(--ink);background:rgba(249,244,236,.9);border-radius:50%;transition:transform .6s var(--ease),color .3s}
.bt-home .bt-pop-close:hover{transform:rotate(90deg);color:var(--navy)}
.bt-home .bt-pop-close svg{width:20px;height:20px}
.bt-home .bt-pop-media{position:relative;min-height:100%;overflow:hidden;background:var(--navy)}
.bt-home .bt-pop-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.bt-home .bt-pop-media::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,54,91,.1) 0%,rgba(0,26,46,.7) 100%)}
.bt-home .bt-pop-seal{position:absolute;left:clamp(18px,3vw,34px);bottom:clamp(18px,3vw,34px);z-index:1;margin:0;display:flex;align-items:flex-end;gap:10px;color:#fff}
.bt-home .bt-pop-seal b{font-family:var(--serif);font-weight:400;font-size:clamp(84px,11vw,132px);line-height:.76;letter-spacing:-.03em}
.bt-home .bt-pop-seal i{font-family:var(--serif);font-style:italic;font-size:clamp(26px,3vw,36px);line-height:1;color:#AED3F5;padding-bottom:4px}
.bt-home .bt-pop-body{padding:clamp(30px,4.4vw,56px) clamp(24px,4vw,52px) clamp(26px,3.6vw,44px)}
.bt-home .bt-pop-body .bt-kicker{font-size:11px;letter-spacing:.2em;line-height:1.5;margin-bottom:18px;padding-right:40px}
.bt-home .bt-pop-h{font-family:var(--serif);font-size:clamp(42px,5.4vw,66px);line-height:1;letter-spacing:-.012em;margin:0;color:var(--ink)}
.bt-home .bt-pop-h em{font-style:italic;color:var(--navy)}
.bt-home .bt-pop-when{font-family:var(--serif);font-style:italic;font-size:clamp(22px,2.4vw,28px);line-height:1.2;color:var(--navy);margin:14px 0 0}
.bt-home .bt-pop-p{color:var(--body);margin:14px 0 0}
.bt-home .bt-pop-cta{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}
.bt-home .bt-pop-cta .bt-btn{flex:1 1 180px;padding:0 16px}
.bt-home .bt-pop-skip{display:inline-block;margin-top:20px;font-size:11.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);border-bottom:1px solid currentColor;padding-bottom:5px;cursor:pointer;transition:color .3s}
.bt-home .bt-pop-skip:hover{color:var(--navy)}

@media (max-width:1180px){
.bt-home .bt-catgrid{grid-template-columns:minmax(0,1fr)}
.bt-home .bt-cat-xl{min-height:clamp(380px,52vw,520px)}
.bt-home .bt-promo-in{grid-template-columns:minmax(0,1fr)}
.bt-home .bt-btp-mos{grid-template-columns:repeat(8,minmax(0,1fr))}
}
@media (max-width:760px){
.bt-home .bt-cat-r{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:clamp(190px,56vw,280px)}
.bt-home .bt-cat-r .bt-cat,.bt-home .bt-cat-r .bt-cat-s{grid-column:span 1}
.bt-home .bt-cat-r .bt-cat:last-child{grid-column:span 2}
.bt-home .bt-cat-xl{min-height:clamp(400px,112vw,520px)}
.bt-home .bt-cat h3{font-size:24px}
.bt-home .bt-cat-xl h3{font-size:44px}
.bt-home .bt-cat-t{padding:16px}
.bt-home .bt-cat-t p{display:none}
.bt-home .bt-cat-xl .bt-cat-t p{display:block;font-size:15.5px}
.bt-home .bt-cat-go{margin-top:12px;font-size:10.5px;letter-spacing:.16em}
.bt-home .bt-cat-no{font-size:16px}
.bt-home .bt-cat-no::before{width:16px}
.bt-home .bt-cat:hover,.bt-home .bt-cat:focus-within{transform:none;box-shadow:none}
.bt-home .bt-sale{grid-template-columns:minmax(0,1fr);padding:30px 22px 34px}
.bt-home .bt-fan{--fw:clamp(92px,27vw,128px);order:-1;height:calc(var(--fw) * 2.3);margin-bottom:8px}
.bt-home .bt-btp{padding:30px 22px}
.bt-home .bt-btp-mos{grid-template-columns:repeat(4,minmax(0,1fr))}
.bt-home .bt-pop{padding:14px;place-items:end center}
.bt-home .bt-pop-card{grid-template-columns:minmax(0,1fr)}
.bt-home .bt-pop-media{min-height:0;height:clamp(150px,42vw,210px)}
.bt-home .bt-pop-seal b{font-size:76px}
.bt-home .bt-pop-body{padding:24px 22px 26px}
}
@media (hover:none){
.bt-home .bt-cat-r .bt-cat-subs{display:none}
}
@media (max-width:1240px){
.bt-home .bt-cards{grid-template-columns:repeat(2,minmax(0,1fr))}
.bt-home .bt-logos li{flex-basis:25%}
.bt-home .bt-room-opts{grid-template-columns:repeat(2,minmax(0,1fr))}
.bt-home .bt-ro:nth-child(3){border-left:0}
.bt-home .bt-ro:nth-child(n+3){border-top:1px solid var(--line)}
}
@media (max-width:1023px){
.bt-home .bt-hero-in{grid-template-columns:minmax(0,1fr);min-height:0;gap:40px}
.bt-home .bt-hero::before{background:linear-gradient(180deg,rgba(17,18,19,.84) 0%,rgba(17,18,19,.66) 55%,rgba(17,18,19,.82) 100%)}
.bt-home .bt-hero-visual{margin:0;max-width:460px}
.bt-home .bt-stage{--w:clamp(110px,18vw,150px)}
.bt-home .bt-head{grid-template-columns:minmax(0,1fr);align-items:start}
.bt-home .bt-viz,.bt-home .bt-story,.bt-home .bt-show,.bt-home .bt-faq{grid-template-columns:minmax(0,1fr)}
.bt-home .bt-story-fig{max-width:560px}
.bt-home .bt-room{transform:none}
.bt-home .bt-map{min-height:380px}
.bt-home .bt-rack{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:44px}
.bt-home .bt-rk-slab{aspect-ratio:3/5;margin:0 12%}
}
@media (max-width:760px){
.bt-home{font-size:16.5px}
.bt-home .bt-cards{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;margin-left:calc(var(--gut) * -1);margin-right:calc(var(--gut) * -1);padding:10px var(--gut) 22px;scroll-padding-left:var(--gut);-webkit-overflow-scrolling:touch}
.bt-home .bt-slot{flex:0 0 80%;scroll-snap-align:start}
.bt-home .bt-slot:hover .bt-card-imgs{transform:none;box-shadow:none}
.bt-home .bt-cf{--sw:clamp(210px,62vw,320px)}
.bt-home .bt-cfs{-webkit-box-reflect:none}
.bt-home .bt-cfs{transform:translateX(calc(var(--d) * var(--sw) * .52)) translateZ(calc(var(--a) * -160px)) rotateY(calc(var(--d) * -30deg))}
.bt-home .bt-cta-row .bt-btn{flex:1 1 220px}
.bt-home .bt-faq-a{padding-right:0}
.bt-home .bt-logos li{flex-basis:33.333%}
.bt-home .bt-logos img{max-height:46px}
.bt-home .bt-room-opts{margin:0}
}
@media (max-width:520px){
.bt-home .bt-rack{grid-template-columns:repeat(2,minmax(0,1fr))}
.bt-home .bt-logos li{flex-basis:50%}
.bt-home .bt-hero-visual{padding:20px}
.bt-home .bt-ribbon li{height:56px}
.bt-home .bt-ro{padding:12px}
.bt-home .bt-ro img{width:36px;height:36px}
.bt-home .bt-qv-cta{grid-template-columns:1fr}
.bt-home .bt-calc-row{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
.bt-home .bt-fan,.bt-home .bt-sale-floor i{animation:none!important}
.bt-home *,.bt-home *::before,.bt-home *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
.bt-home .bt-slab{animation:none;transform:rotateX(5deg) rotateY(-26deg)}
.bt-home .bt-sheen,.bt-home .bt-slab-shadow,.bt-home .bt-hb1,.bt-home .bt-hb2{animation:none}
.bt-home .bt-room{transform:none}
.bt-home .bt-ribbon-track{animation:none;display:block;width:auto}
.bt-home .bt-ribbon ul{flex-wrap:wrap;justify-content:center;padding:8px 0}
.bt-home .bt-ribbon ul+ul{display:none}
.bt-home .bt-ribbon li::after{margin:0 14px}
.bt-home .bt-ribbon li{height:40px}
.bt-home .bt-ribbon{-webkit-mask-image:none;mask-image:none}
}
html:has(.bt-home .bt-qv:not(.bt-qv0):checked){overflow:hidden}
